import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextLong()) {
            return;
        }
        long n = scanner.nextLong();
        long t = scanner.nextLong();

        long ans = 0;
        if (t == 0) {
            ans = n;
        } else if (t == 1) {
            ans = n * (n - 1);
        } else if (t == 2) {
            ans = n * (n - 1) * (n - 2) / 6;
        }

        System.out.println(ans);
    }
}
